import React, { useState, useEffect } from 'react';
import { Chart } from 'primereact/chart';

export default function LineStyles() {
    const [chartData, setChartData] = useState({});
    const [chartOptions, setChartOptions] = useState({});

    useEffect(() => {
        const targetElement = document.body ?? document.documentElement;
        const documentStyle = getComputedStyle(targetElement);
        const getColor = (variable) => {
            const value = documentStyle.getPropertyValue(variable)?.trim();
            if (value) {
                return value;
            }
            const rootStyle = getComputedStyle(document.documentElement);
            const rootValue = rootStyle.getPropertyValue(variable)?.trim();
            return rootValue;
        };
        const textColor = getColor('--uls-text-color');
        const textColorSecondary = getColor('--uls-secondary-text-color');
        const surfaceBorder = getColor('--uls-primary-border-color');
        const data = {
            labels: ['January', 'February', 'March', 'April', 'May', 'June', 'July'],
            datasets: [
                {
                    label: 'First Dataset',
                    data: [65, 59, 80, 81, 56, 55, 40],
                    fill: false,
                    tension: 0.4,
                    borderColor: getColor('--uls-primary-color')
                },
                {
                    label: 'Second Dataset',
                    data: [28, 48, 40, 19, 86, 27, 90],
                    fill: false,
                    borderDash: [5, 5],
                    tension: 0.4,
                    borderColor: getColor('--uls-warning-color')
                },
                {
                    label: 'Third Dataset',
                    data: [12, 51, 62, 33, 21, 62, 45],
                    fill: true,
                    borderColor: getColor('--uls-success-color'),
                    tension: 0.4,
                    backgroundColor: 'rgba(255,167,38,0.2)'
                }
            ]
        };
        const options = {
            maintainAspectRatio: false,
            aspectRatio: 0.6,
            plugins: {
                legend: {
                    labels: {
                        color: textColor
                    }
                }
            },
            scales: {
                x: {
                    ticks: {
                        color: textColorSecondary
                    },
                    grid: {
                        color: surfaceBorder
                    }
                },
                y: {
                    ticks: {
                        color: textColorSecondary
                    },
                    grid: {
                        color: surfaceBorder
                    }
                }
            }
        };

        setChartData(data);
        setChartOptions(options);
    }, []);

    return (
        <Chart type="line" data={chartData} options={chartOptions} />
    )

}